// SQL text for the generated golden-replay test. Kept apart from build.ts so
// the data emitter stays short and the rules below read as a block.

export const HEADER_SQL = (
  source: string
): string => `-- GENERATED by scripts/qa/golden-replay/build.ts from
-- supabase/tests/fixtures/golden-replay/legacy-trial-27835.json. Do not edit by
-- hand: pnpm qa:golden-replay:build rewrites it and the golden-replay vitest
-- fails when it is stale.
--
-- MYK9-1647: golden replay. A real, already-judged and published trial is the
-- answer key for scoring -> placement. Source: ${source}.
--
-- Every other placement test uses invented fixtures. This one loads the real
-- scoring inputs of every class in the trial, calls the real
-- recalculate_class_placements, and compares our final_placement per entry with
-- the placement v3 published. Any disagreement raises ONE exception listing
-- every entry (class, armband, ours, v3, reason).
--
-- Named, deliberate rule differences (the only tolerances; nothing else is
-- filtered):
--   RULE 1 (exact tie in 1st-4th, MYK9-1473): v3 gave tied dogs distinct
--     consecutive places in an order nobody recorded; ours orders a tie by a
--     recorded coin flip. A ribbon tie therefore matches when the SET of
--     places over the tie group matches, not entry by entry.
--   RULE 2 (exact tie below 4th, MYK9-1473): ours shares the competition rank
--     (5, 5, 7), where v3 gave consecutive places. A tie group whose best v3
--     place is past 4th matches when every member holds that best place.
--   RULE 3 (non-qualifiers): ours places qualified, scored runs only. An NQ,
--     absent, excused or withdrawn entry must be unplaced in ours AND carry no
--     placement in v3 (a v3 placement on a non-qualifier is itself reported).
--   A "tie" is the same total_faults AND search_time_seconds among qualified
--     entries of one class (the rule recalculate_class_placements ranks on;
--     this trial is not a nationals show, so points are not a ranking key).
--
-- Known-answer controls inside this file (a replay that cannot go red proves
-- nothing): CONTROL A swaps the v3 places of two untied dogs and requires the
-- comparison to report a diff; CONTROL B swaps two members of a ribbon tie and
-- requires it to report none. Both run on an answer key copied from our own
-- placements, so they hold whatever the real replay finds (the tolerance is real and not a blanket pass).
--
-- Run: pnpm qa:golden-replay (throwaway local stack), or in CI by
-- scripts/qa/run-behavioral-sql-tests.sh. All fixtures roll back.

BEGIN;

ALTER TABLE public.classes DISABLE TRIGGER trg_notify_class_status_push;
ALTER TABLE public.classes DISABLE TRIGGER trg_notify_class_results_push;

CREATE TEMP TABLE golden_class (
  class_key text PRIMARY KEY,
  element text NOT NULL,
  level text NOT NULL,
  section text NOT NULL,
  time_limit_seconds integer,
  num_areas integer NOT NULL,
  class_id uuid NOT NULL DEFAULT gen_random_uuid()
);

CREATE TEMP TABLE golden_expected (
  class_key text NOT NULL,
  armband text NOT NULL,
  result_status text NOT NULL,
  search_time_seconds numeric NOT NULL,
  total_faults integer NOT NULL,
  total_correct_finds integer NOT NULL,
  total_incorrect_finds integer NOT NULL,
  area1_time_seconds numeric NOT NULL,
  area1_correct integer NOT NULL,
  area1_incorrect integer NOT NULL,
  area1_faults integer NOT NULL,
  time_over_limit boolean NOT NULL,
  points_earned integer NOT NULL,
  v3_place integer,
  PRIMARY KEY (class_key, armband)
);
`;

export const COMPARISON_SQL = `
-- Fixture: one club, show, trial; one class per fixture class.
INSERT INTO public.clubs (id, name)
VALUES ('00000000-0000-0000-0000-000000164701', 'MYK9-1647 golden replay club');
INSERT INTO public.shows (id, name, organization, start_date, end_date, is_nationals, club_id)
VALUES ('00000000-0000-0000-0000-000000164702', 'MYK9-1647 golden replay show', 'AKC',
        current_date, current_date, false, '00000000-0000-0000-0000-000000164701');
INSERT INTO public.trials (id, show_id, name, date)
VALUES ('00000000-0000-0000-0000-000000164703', '00000000-0000-0000-0000-000000164702',
        'MYK9-1647 golden replay trial', current_date);

INSERT INTO public.classes (id, trial_id, name, status, element, level, section, time_limit_seconds, num_areas)
SELECT c.class_id, '00000000-0000-0000-0000-000000164703', c.class_key, 'upcoming',
       c.element, c.level, nullif(c.section, ''), c.time_limit_seconds, c.num_areas
FROM pg_temp.golden_class c;

-- Scoring inputs exactly as v3 recorded them. Rows insert before the explicit
-- recalculation below, so the entry triggers' own placement pass is not trusted:
-- the replay calls recalculate_class_placements itself over the finished data.
INSERT INTO public.entries (
  class_id, show_id, trial_id, armband, entry_status, check_in_status, is_scored, result_status,
  search_time_seconds, total_faults, total_correct_finds, total_incorrect_finds,
  area1_time_seconds, area1_correct, area1_incorrect, area1_faults, time_over_limit, points_earned
)
SELECT c.class_id, '00000000-0000-0000-0000-000000164702', '00000000-0000-0000-0000-000000164703',
       g.armband, 'checked-in', 'checked-in', true, g.result_status,
       g.search_time_seconds, g.total_faults, g.total_correct_finds, g.total_incorrect_finds,
       g.area1_time_seconds, g.area1_correct, g.area1_incorrect, g.area1_faults,
       g.time_over_limit, g.points_earned
FROM pg_temp.golden_expected g
JOIN pg_temp.golden_class c USING (class_key);

-- The comparison. p_expected names a table shaped like golden_expected, so the
-- same logic runs over the real answer key and over the controls' altered copies.
CREATE FUNCTION pg_temp.golden_diffs(p_expected regclass)
RETURNS TABLE (class_key text, armband text, result_status text, ours integer, v3 integer, reason text)
LANGUAGE plpgsql AS $fn$
BEGIN
  RETURN QUERY EXECUTE format($q$
    WITH x AS (
      SELECT g.class_key, g.armband, g.result_status, g.total_faults, g.search_time_seconds,
             g.v3_place, e.final_placement AS ours
      FROM %s g
      JOIN pg_temp.golden_class c ON c.class_key = g.class_key
      LEFT JOIN public.entries e ON e.class_id = c.class_id AND e.armband = g.armband
    ),
    grp AS (
      SELECT class_key, total_faults, search_time_seconds,
             count(*) AS n,
             min(v3_place) AS best,
             array_agg(v3_place ORDER BY v3_place) AS v3_set,
             array_agg(ours ORDER BY ours NULLS FIRST) AS ours_set
      FROM x WHERE result_status = 'qualified'
      GROUP BY class_key, total_faults, search_time_seconds
    )
    SELECT x.class_key, x.armband, x.result_status, x.ours, x.v3_place,
           CASE
             WHEN x.result_status <> 'qualified' AND x.ours IS NOT NULL
               THEN 'RULE 3: ours placed a non-qualifier'
             WHEN x.result_status <> 'qualified' AND x.v3_place IS NOT NULL
               THEN 'RULE 3: v3 placed a non-qualifier'
             WHEN x.result_status <> 'qualified' THEN NULL
             WHEN gp.n = 1 AND x.ours IS DISTINCT FROM x.v3_place
               THEN 'untied dog placed differently'
             WHEN gp.n > 1 AND gp.best <= 4 AND gp.ours_set IS DISTINCT FROM gp.v3_set
               THEN 'RULE 1: ribbon tie place set differs (ours ' || gp.ours_set::text
                    || ' v3 ' || gp.v3_set::text || ')'
             WHEN gp.n > 1 AND gp.best > 4 AND x.ours IS DISTINCT FROM gp.best
               THEN 'RULE 2: tie below 4th should share place ' || gp.best
           END AS reason
    FROM x
    LEFT JOIN grp gp USING (class_key, total_faults, search_time_seconds)
    ORDER BY x.class_key, x.v3_place NULLS LAST, x.armband
  $q$, p_expected) ;
END;
$fn$;

DO $$
DECLARE
  v_diffs text;
  v_n integer;
  v_base integer;
  v_classes integer;
  v_qualified integer;
  v_nonq integer;
  v_ribbon_ties integer;
  v_lower_ties integer;
  v_pair record;
  v_tie record;
BEGIN
  -- Place every class through the real function.
  PERFORM public.recalculate_class_placements(
    (SELECT array_agg(class_id) FROM pg_temp.golden_class), false);

  SELECT count(*) INTO v_classes FROM pg_temp.golden_class;
  SELECT count(*) FILTER (WHERE result_status = 'qualified'),
         count(*) FILTER (WHERE result_status <> 'qualified')
    INTO v_qualified, v_nonq FROM pg_temp.golden_expected;
  SELECT count(*) FILTER (WHERE best <= 4), count(*) FILTER (WHERE best > 4)
    INTO v_ribbon_ties, v_lower_ties
  FROM (
    SELECT min(v3_place) AS best FROM pg_temp.golden_expected
    WHERE result_status = 'qualified'
    GROUP BY class_key, total_faults, search_time_seconds HAVING count(*) > 1
  ) t;

  -- Guard the fixture: the replay is vacuous without ties, an NQ and 2+ classes.
  IF v_classes < 2 OR v_ribbon_ties + v_lower_ties = 0 OR v_nonq = 0
     OR NOT EXISTS (SELECT 1 FROM pg_temp.golden_expected WHERE result_status = 'nq') THEN
    RAISE EXCEPTION 'FAIL golden replay fixture is too thin: % classes, % tie groups, % non-qualifiers',
      v_classes, v_ribbon_ties + v_lower_ties, v_nonq;
  END IF;
  IF (SELECT count(*) FROM public.entries e JOIN pg_temp.golden_class c USING (class_id)
      WHERE e.final_placement IS NOT NULL) = 0 THEN
    RAISE EXCEPTION 'FAIL golden replay: recalculate_class_placements placed nobody';
  END IF;

  -- The replay itself (reported at the end, after the controls have run).
  SELECT count(*), string_agg(
           format('  %s | armband %s | %s | ours %s | v3 %s | %s',
                  d.class_key, d.armband, d.result_status, coalesce(d.ours::text, 'none'),
                  coalesce(d.v3::text, 'none'), d.reason),
           E'\\n' ORDER BY d.class_key, d.v3 NULLS LAST, d.armband)
    INTO v_base, v_diffs
  FROM pg_temp.golden_diffs('pg_temp.golden_expected') d WHERE d.reason IS NOT NULL;

  -- The controls run on golden_ours: the answer key rewritten to what our
  -- function placed, which agrees with itself by construction, so they hold
  -- whatever the real replay finds.
  CREATE TEMP TABLE golden_ours AS TABLE pg_temp.golden_expected;
  UPDATE pg_temp.golden_ours o SET v3_place = e.final_placement
  FROM pg_temp.golden_class c, public.entries e
  WHERE c.class_key = o.class_key AND e.class_id = c.class_id AND e.armband = o.armband;
  SELECT count(*) INTO v_n FROM pg_temp.golden_diffs('pg_temp.golden_ours') d WHERE d.reason IS NOT NULL;
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'FAIL golden replay: our own placements disagree with themselves (% diffs); the comparison is broken', v_n;
  END IF;

  -- CONTROL A: swap the v3 places of two untied dogs (1st and 2nd of one class).
  CREATE TEMP TABLE golden_swapped AS TABLE pg_temp.golden_ours;
  SELECT a.class_key, a.armband AS first_armband, b.armband AS second_armband INTO v_pair
  FROM pg_temp.golden_ours a
  JOIN pg_temp.golden_ours b ON b.class_key = a.class_key AND a.v3_place = 1 AND b.v3_place = 2
  WHERE a.result_status = 'qualified' AND b.result_status = 'qualified'
    AND (SELECT count(*) FROM pg_temp.golden_ours t WHERE t.class_key = a.class_key
         AND t.result_status = 'qualified'
         AND t.total_faults = a.total_faults AND t.search_time_seconds = a.search_time_seconds) = 1
    AND (SELECT count(*) FROM pg_temp.golden_ours t WHERE t.class_key = b.class_key
         AND t.result_status = 'qualified'
         AND t.total_faults = b.total_faults AND t.search_time_seconds = b.search_time_seconds) = 1
  ORDER BY a.class_key LIMIT 1;
  IF v_pair.class_key IS NULL THEN
    RAISE EXCEPTION 'FAIL golden replay control A: no class with an untied 1st and 2nd to swap';
  END IF;
  UPDATE pg_temp.golden_swapped s
     SET v3_place = CASE s.armband WHEN v_pair.first_armband THEN 2 ELSE 1 END
   WHERE s.class_key = v_pair.class_key
     AND s.armband IN (v_pair.first_armband, v_pair.second_armband);
  SELECT count(*) INTO v_n FROM pg_temp.golden_diffs('pg_temp.golden_swapped') d WHERE d.reason IS NOT NULL;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'FAIL golden replay control A: swapping the v3 places of armbands % and % in % found no diff; the comparison cannot go red',
      v_pair.first_armband, v_pair.second_armband, v_pair.class_key;
  END IF;
  RAISE NOTICE 'PASS control A: swapping two untied v3 places is reported (% diffs)', v_n;

  -- CONTROL B: swapping two members of a ribbon tie is tolerated (RULE 1).
  TRUNCATE pg_temp.golden_swapped;
  INSERT INTO pg_temp.golden_swapped SELECT * FROM pg_temp.golden_ours;
  SELECT t.class_key, t.total_faults, t.search_time_seconds,
         min(t.armband) FILTER (WHERE t.v3_place = lo.best) AS a_armband,
         min(t.armband) FILTER (WHERE t.v3_place = lo.best + 1) AS b_armband
    INTO v_tie
  FROM pg_temp.golden_ours t
  JOIN (SELECT class_key, total_faults, search_time_seconds, min(v3_place) AS best
        FROM pg_temp.golden_ours WHERE result_status = 'qualified'
        GROUP BY 1, 2, 3 HAVING count(*) > 1 AND min(v3_place) <= 3) lo
    USING (class_key, total_faults, search_time_seconds)
  WHERE t.result_status = 'qualified'
  GROUP BY t.class_key, t.total_faults, t.search_time_seconds, lo.best
  ORDER BY t.class_key, lo.best LIMIT 1;
  IF v_tie.class_key IS NULL THEN
    RAISE EXCEPTION 'FAIL golden replay control B: no ribbon tie in the fixture to swap inside';
  END IF;
  UPDATE pg_temp.golden_swapped s
     SET v3_place = CASE s.armband WHEN v_tie.a_armband THEN
                      (SELECT v3_place FROM pg_temp.golden_ours x WHERE x.class_key = s.class_key AND x.armband = v_tie.b_armband)
                    ELSE
                      (SELECT v3_place FROM pg_temp.golden_ours x WHERE x.class_key = s.class_key AND x.armband = v_tie.a_armband)
                    END
   WHERE s.class_key = v_tie.class_key AND s.armband IN (v_tie.a_armband, v_tie.b_armband);
  SELECT count(*) INTO v_n FROM pg_temp.golden_diffs('pg_temp.golden_swapped') d WHERE d.reason IS NOT NULL;
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'FAIL golden replay control B: swapping two members of a ribbon tie was reported (% diffs)', v_n;
  END IF;
  RAISE NOTICE 'PASS control B: swapping two members of a ribbon tie is tolerated (RULE 1)';

  IF v_base > 0 THEN
    RAISE EXCEPTION E'FAIL golden replay: % entries disagree with the published v3 results\\n%', v_base, v_diffs;
  END IF;
  RAISE NOTICE 'PASS golden replay: % classes, % qualified entries placed as v3 published (% ribbon tie groups matched as sets, % tie groups below 4th share a place), % non-qualifiers unplaced',
    v_classes, v_qualified, v_ribbon_ties, v_lower_ties, v_nonq;
END;
$$;
`;

export const TAIL_SQL = `
ROLLBACK;
`;
